mapper.select:
SELECT b.id AS bank_id, b.country_code, b.currency, b.bank_code, b.bank_name, b.bank_short_name, m.id AS mapping_id, #{pspId} AS psp_id, m.psp_bank_code, m.status AS status, m.remark AS remark FROM sys_bank b LEFT JOIN psp_bank_mapping m ON m.country_code = b.country_code AND m.currency = b.currency AND m.bank_code = b.bank_code AND m.psp_id = #{pspId} WHERE b.country_code = #{countryCode}
AND b.currency = #{currency}
AND b.status IN (1, 2) ORDER BY b.sort ASC, b.bank_code ASC
